def compute(vars):
    old_price = vars["v1"]
    new_price = vars["v2"]

    if old_price == 0:
        return {"value": None, "trace": {"old_price": old_price, "new_price": new_price, "output_meta": {"currency": None, "scale": None, "unit": "percentage"}}}

    change_ratio = (new_price - old_price) / old_price
    price_return_percentage = change_ratio * 100

    return {
        "value": price_return_percentage,
        "trace": {
            "old_price": old_price,
            "new_price": new_price,
            "change_ratio": change_ratio,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "percentage"
            }
        }
    }
